import { NextRequest, NextResponse } from 'next/server'
import { readFile, stat } from 'fs/promises'
import { join } from 'path'
import { lookup } from 'mime-types'
import { getServerSession } from 'next-auth'
import { authOptions } from '@/lib/auth'
import { prisma } from '@/lib/prisma'
import { findCallerPurchase } from '@/lib/purchase-access'
import { SessionUser } from '@/types'

const UPLOADS_DIR = join(process.cwd(), 'public', 'uploads')

// Stored names are generated by /api/upload and never contain a separator.
const SAFE_NAME = /^[a-zA-Z0-9][a-zA-Z0-9._-]*$/

// Only these are rendered in the browser. Everything else (html, svg, ...) is
// sent as a download so an uploaded file can never run as a page on our origin.
function canRenderInline(mimeType: string) {
  if (mimeType === 'image/svg+xml') {
    return false
  }

  return (
    mimeType.startsWith('image/') ||
    mimeType.startsWith('video/') ||
    mimeType.startsWith('audio/') ||
    mimeType === 'application/pdf'
  )
}

const notFound = () => new NextResponse('Not Found', { status: 404 })

export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ path: string[] }> },
) {
  try {
    const { path } = await params

    // This route serves uploaded content only, and only by its stored name.
    if (
      path.length !== 2 ||
      path[0] !== 'uploads' ||
      !SAFE_NAME.test(path[1])
    ) {
      return notFound()
    }

    const storedName = path[1]

    const file = await prisma.file.findFirst({
      where: { filepath: `/api/files/uploads/${storedName}` },
      include: {
        content: {
          include: {
            link: {
              include: {
                profile: { select: { userId: true } },
              },
            },
          },
        },
      },
    })

    if (!file) {
      return notFound()
    }

    // A file is served to the seller who owns it, or to a buyer holding a paid
    // purchase of the link it belongs to. Everyone else gets a 404 so the
    // response does not confirm that the file exists.
    const link = file.content.link
    const session = await getServerSession(authOptions)
    const isOwner =
      Boolean(session?.user) &&
      (session!.user as SessionUser).id === link.profile.userId

    if (!isOwner) {
      const purchase = link.isActive
        ? await findCallerPurchase(request, link.id)
        : null

      if (!purchase?.paid) {
        return notFound()
      }
    }

    const fullPath = join(UPLOADS_DIR, storedName)

    const fileStats = await stat(fullPath)
    if (!fileStats.isFile()) {
      return notFound()
    }

    const fileBuffer = await readFile(fullPath)
    const mimeType = lookup(fullPath) || 'application/octet-stream'
    const downloadName = encodeURIComponent(file.filename || storedName)

    return new NextResponse(fileBuffer, {
      headers: {
        'Content-Type': mimeType,
        'Content-Length': fileStats.size.toString(),
        'Content-Disposition': `${
          canRenderInline(mimeType) ? 'inline' : 'attachment'
        }; filename*=UTF-8''${downloadName}`,
        'X-Content-Type-Options': 'nosniff',
        // Paid content: never store it in a shared cache.
        'Cache-Control': 'private, max-age=3600',
      },
    })
  } catch (error) {
    console.error('Error serving file:', error)
    return notFound()
  }
}
